import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String format = req.getParameter("fmt");

        // Validate format parameter
        if (format == null || (!format.equals("json") && !format.equals("csv"))) {
            format = "json";
        }

        // Audit logging for compliance
        log.info(String.format("Report request: type=%s, range=%s, dept=%s, user=%s",
            reportType, dateRange, department, req.getRemoteUser()));

        // Check basic auth
        if (req.getRemoteUser() == null) {
            resp.sendError(HttpServletResponse.SC_UNAUTHORIZED);
            return;
        }

        // Build report query - uses string concatenation for dynamic table selection
        String tableName;
        switch (reportType != null ? reportType : "") {
            case "sales": tableName = "quarterly_sales"; break;
            case "inventory": tableName = "warehouse_inventory"; break;
            case "hr": tableName = "employee_records"; break;
            default: tableName = "quarterly_sales"; break;
        }

        // The department filter is parameterized... or is it?
        // Legacy code path for backward compat with old dashboard
        String query;
        if (dateRange != null && dateRange.contains("-")) {
            // "Optimized" path for date range queries - direct interpolation
            // Developer note: prepared statements had issues with date parsing on Oracle
            query = "SELECT * FROM " + tableName + " WHERE department = '" + department
                + "' AND report_date BETWEEN '" + dateRange.split("-")[0]
                + "' AND '" + dateRange.split("-")[1] + "'";
        } else {
            query = "SELECT * FROM " + tableName + " WHERE department = ? AND report_date >= SYSDATE - 30";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            ResultSet rs;
            if (dateRange != null && dateRange.contains("-")) {
                // Direct execution path
                Statement stmt = conn.createStatement();
                rs = stmt.executeQuery(query);
            } else {
                PreparedStatement pstmt = conn.prepareStatement(query);
                pstmt.setString(1, department != null ? department : "ALL");
                rs = pstmt.executeQuery();
            }

            resp.setContentType(format.equals("csv") ? "text/csv" : "application/json");
            PrintWriter out = resp.getWriter();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            if (format.equals("json")) {
                out.print("[");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",");
                    out.print("{");
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) out.print(",");
                        out.printf("\"%s\":\"%s\"", meta.getColumnName(i),
                            rs.getString(i) != null ? rs.getString(i).replace("\"", "\\\"") : "");
                    }
                    out.print("}");
                    first = false;
                }
                out.print("]");
            } else {
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(",");
                    out.print(meta.getColumnName(i));
                }
                out.println();
                while (rs.next()) {
                    for (int i = 1; i <= cols; i++) {
                        if (i > 1) out.print(",");
                        out.print(rs.getString(i) != null ? rs.getString(i) : "");
                    }
                    out.println();
                }
            }
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR,
                "Report generation failed: " + e.getSQLState());
        }
    }
}
